W, H = len(outp[0]), len(outp)

# Get marker positions
markers = set()
for r, row in enumerate(inp):
    for c, val in enumerate(row):
        if val == 2:
            markers.add((r, c))

# Fill cells that are between markers
def fill_between_adjacent(markers_in_line, start_line, start_line_type):
    """Fill cells between adjacent markers in a line"""
    fills = set()
    if start_line_type == 'row':
        for r in start_line:
            row_markers = sorted([c for _, c in markers if (r, c) in markers])
            for i in range(len(row_markers) - 1):
                c1, c2 = row_markers[i], row_markers[i+1]
                fills.update((r, c) for c in range(c1 + 1, c2))
    elif start_line_type == 'col':
        for c in start_line:
            col_markers = sorted([r for r, _ in markers if (r, c) in markers])
            for i in range(len(col_markers) - 1):
                r1, r2 = col_markers[i], col_markers[i+1]
                fills.update((r, c) for r in range(r1 + 1, r2))
